import json,html,pathlib
root=pathlib.Path('products/research/2026-10-27');d=json.loads((root/'checked.json').read_text());by={i['index']:i for i in d['items']};notes={35:('First sample choice','Compact, clean crossbody silhouette with a strong price. Supplier describes genuine leather/sheepskin; verify on a sample.'),67:('Structured everyday option','Neutral top-handle design fits the store. Supplier describes cowhide; confirm the grain grade rather than advertising it unverified.'),15:('Premium-style shoulder option','Understated silhouette, two neutral colors and useful carrying imagery. Higher total cost; supplier leather claims need sample verification.'),23:('Value bucket option','Simple bucket shape in three restrained colors. Supplier says composite cowhide: do not describe it as full-grain leather.'),64:('Budget alternative — PU','Good visual fit and low cost, but explicitly PU. Keep separate from the leather range and check stitching, lining and handle quality on a sample.')}
esc=lambda x:html.escape(str(x));cards=[];md=['# CJ product shortlist — 27 October 2026','','118 unique search results across five keywords; 46 main photos compared; 10 products checked for US and UK freight. Four candidates shortlisted by visual fit and quoted cost, not proven physical quality.','','All figures USD. Freight is for one selected variant, one item, China origin, without a destination postcode. Other colors/variants and addresses may differ. Product + freight excludes any unquoted tax, duty, payment fees, returns, advertising and margin. CJ transit estimates are not guaranteed delivery dates or processing times. No products saved to CJ or published to Shopify.','']
