 for code,label in [('US','US'),('GB','UK')]:
  routes=sorted([q for q in i['quotes'][code] if q.get('logisticPrice') is not None],key=lambda q:float(q['logisticPrice']));q=routes[0];price=float(q['logisticPrice']);line=f'{label}: freight ${price:.2f}; product + freight ${cost+price:.2f}; {q["logisticName"]}; CJ transit estimate {q["logisticAging"]}.';md.append(line);quotes.append('<p>'+esc(line)+'</p>')
 inv=i.get('inventory',{}).get('inventories',[]);stock='; '.join(f'{x["countryCode"]}: CJ warehouse {x["cjInventoryNum"]}, supplier/factory {x["factoryInventoryNum"]}' for x in inv) or 'Inventory check pending';md+=['Inventory snapshot: '+stock,'']
 cards.append(f'<article><img src="thumbs/{k}.jpg" alt="{esc(i["candidate"]["nameEn"])}"><div><small>{rank} · {esc(tag)}</small><h2>{esc(i["candidate"]["sku"])}</h2><h3>{esc(i["candidate"]["nameEn"])}</h3><p>{esc(note)}</p><p>Selected variant: {esc(v["variantKey"])} · Supplier ${cost:.2f}</p>{"".join(quotes)}<p class="muted">{esc(stock)}</p></div></article>')
